INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Zentralelemente > Arbeitsspeicher RAM
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann der Arbeitsspeicher unabhängig vom Mainboard-Typ ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "RAM-Typ muss mit Slots kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl des Arbeitsspeichers immer die Softwareanforderungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Software definiert Speicherbedarf"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Geschwindigkeit des Arbeitsspeichers irrelevant für die Systemleistung?', 2, '[{"text": "Nein", "correct": true, "because": "Schneller RAM verbessert Performance"}, {"text": "Ja", "correct": false, "because": "Geschwindigkeit beeinflusst Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Können verschiedene RAM-Typen wie DDR3 und DDR4 gleichzeitig auf einem Mainboard genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Standards sind inkompatibel"}, {"text": "Ja", "correct": false, "because": "Mainboard unterstützt nur einen Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist mehr Arbeitsspeicher immer gleichbedeutend mit besserer Leistung?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzen hängt von Anwendung ab"}, {"text": "Ja", "correct": false, "because": "Überschuss bringt keinen Vorteil"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl des Arbeitsspeichers am wichtigsten?', 3, '[{"text": "Kapazität", "correct": true, "because": "Bestimmt Speichermenge für Anwendungen"}, {"text": "Farbe der Module", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Marke", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit wird üblicherweise zur Angabe der Arbeitsspeichergröße verwendet?', 2, '[{"text": "Gigabyte (GB)", "correct": true, "because": "Standardmaß für Kapazität"}, {"text": "Megahertz (MHz)", "correct": false, "because": "Geschwindigkeit, nicht Größe"}, {"text": "Watt (W)", "correct": false, "because": "Leistungsaufnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher RAM-Typ ist aktuell (Stand 2025) am weitesten verbreitet?', 2, '[{"text": "DDR4", "correct": true, "because": "Dominant in modernen Systemen"}, {"text": "DDR3", "correct": false, "because": "Älterer Standard"}, {"text": "SDRAM", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bestimmt die maximale Arbeitsspeichermenge eines Systems?', 3, '[{"text": "Mainboard", "correct": true, "because": "Slots und Chipsatz definieren Grenze"}, {"text": "Prozessor", "correct": false, "because": "Indirekt relevant"}, {"text": "Netzteil", "correct": false, "because": "Unterstützend, nicht limitierend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft des Arbeitsspeichers beeinflusst die Datenübertragungsrate?', 2, '[{"text": "Taktfrequenz", "correct": true, "because": "Höhere Frequenz, schnellerer Zugriff"}, {"text": "Spannung", "correct": false, "because": "Energie, nicht Geschwindigkeit"}, {"text": "Modulgröße", "correct": false, "because": "Physisch, nicht funktional"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Leistung des Arbeitsspeichers?', 4, '[{"text": "Kapazität", "correct": true, "because": "Mehr Speicher für Anwendungen"}, {"text": "Taktfrequenz", "correct": true, "because": "Schnellere Datenverarbeitung"}, {"text": "Latenzzeit", "correct": true, "because": "Kürzere Latenz, besserer Zugriff"}, {"text": "Farbe der Module", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte müssen bei der Auswahl des Arbeitsspeichers beachtet werden?', 3, '[{"text": "Mainboard-Kompatibilität", "correct": true, "because": "Slots und Typ müssen passen"}, {"text": "Softwareanforderungen", "correct": true, "because": "Bestimmen Kapazität"}, {"text": "Taktfrequenz", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Gewicht des Moduls", "correct": false, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl des Arbeitsspeichers auftreten?', 3, '[{"text": "Inkompatibilität mit Mainboard", "correct": true, "because": "Falscher Typ oder Slot"}, {"text": "Unzureichende Kapazität", "correct": true, "because": "Software läuft nicht flüssig"}, {"text": "Zu hohe Latenz", "correct": true, "because": "Verzögert Zugriff"}, {"text": "Falsche Farbkombination", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen Arbeitsspeicher zukunftssicher?', 4, '[{"text": "Hohe Kapazität", "correct": true, "because": "Für wachsende Anforderungen"}, {"text": "Neuer Standard (z. B. DDR5)", "correct": true, "because": "Aktuelle Technologie"}, {"text": "Hohe Taktfrequenz", "correct": true, "because": "Schnellere Datenrate"}, {"text": "Integrierte Kühlung", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen erfordern besonders viel Arbeitsspeicher?', 3, '[{"text": "Videobearbeitung", "correct": true, "because": "Große Datenmengen"}, {"text": "Virtualisierung", "correct": true, "because": "Mehrere Systeme parallel"}, {"text": "3D-Rendering", "correct": true, "because": "Hoher Speicherbedarf"}, {"text": "Textverarbeitung", "correct": false, "because": "Geringer Bedarf"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Taktfrequenz des Arbeitsspeichers wird in MHz oder GHz angegeben. b) Mehr RAM verbessert immer die Prozessorleistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Frequenz ja, RAM nicht immer CPU"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": "false", "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DDR4-RAM ist mit DDR3-Mainboards inkompatibel. b) Die Arbeitsspeichergröße ist in Watt angegeben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DDR4 ja, Größe in GB"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Arbeitsspeicher beeinflusst die Systemgeschwindigkeit. b) Alle Mainboards unterstützen beliebige RAM-Kapazitäten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit ja, Kapazität begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Software wie Videobearbeitung benötigt viel RAM. b) RAM-Taktfrequenz ist für einfache Büroanwendungen irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Videobearbeitung ja, Frequenz immer relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die maximale RAM-Kapazität hängt vom Mainboard ab. b) DDR5 ist langsamer als DDR4.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mainboard ja, DDR5 schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

